/// at every block's end, and every trial's reading beside the run by its hash. Written from the
/// one run's dumps (ADR-0142), each arm read after every one of H-25's tables was held.
static RELEASED_COSTED_1024: LazyLock<[&[Costed]; 2]> = LazyLock::new(|| DATA_FILE.read("RELEASED_COSTED_1024"));
static RELEASED_HEARD_1024: LazyLock<[&[Heard]; 2]> = LazyLock::new(|| DATA_FILE.read("RELEASED_HEARD_1024"));
static RELEASED_ELIGIBLE_1024: LazyLock<[&[Eligible]; 2]> = LazyLock::new(|| DATA_FILE.read("RELEASED_ELIGIBLE_1024"));
static RELEASED_MARGINS_1024: LazyLock<[&[Margins]; 2]> = LazyLock::new(|| DATA_FILE.read("RELEASED_MARGINS_1024"));
static RELEASED_COUPLINGS_1024: LazyLock<[&[[[i64; 2]; 2]]; 2]> = LazyLock::new(|| DATA_FILE.read("RELEASED_COUPLINGS_1024"));
const RELEASED_HASH_1024: [u64; 2] = [0x9466ed8c8e715027, 0xe34424a493330239];
/// The cost per mapping, the rule's left side: 0.560, 0.514, 0.594 and 0.558 of the signal from
