const ROTATIONS: u32 = PERIOD;

/// The scale ADR-0132's split took, which the critic's arithmetic keeps on another network.
const SPLIT_SCALE: u8 = VALUED_CRITIC.scale;

/// ADR-0132's reason for the split, as the bound the restated arithmetic holds it to: the step's
/// dead band, $2^k$, under one per cent of the reward, read as `band × 100 < reward`.
const DEAD_BAND_PER_CENT: i64 = 1;

/// The shift the critic's rule holds past it (ADR-0168): the largest whose dead band is under
/// `DEAD_BAND_PER_CENT` of the reward, 9, a band of 512 of 65 536. It is ADR-0132's own shift,
/// which a volley of 33 to 64 units reaches with ADR-0132's scale.
const SHIFT_HELD: u8 = VALUED_CRITIC.shift;
const _: () = assert!(
    SHIFT_HELD == 9
        && (1i64 << SHIFT_HELD) * 100 < REWARD_Q16 as i64 * DEAD_BAND_PER_CENT
        && (1i64 << (SHIFT_HELD + 1)) * 100 >= REWARD_Q16 as i64 * DEAD_BAND_PER_CENT
);

/// The widest sum of a shift and a scale the arithmetic scans to: the loader's two bounds.
const CRITIC_SUM_MAX: u32 = CRITIC_SHIFT_MAX as u32 + CRITIC_SCALE_MAX as u32;
const _: () = assert!(CRITIC_SUM_MAX == 44 && SPLIT_SCALE == 2);

// ----------------------------------------------------------- the rules (ADR-0165, ADR-0167)

/// What each rule returned on a network, in the order of the derivations (ADR-0165): none where a
/// rule returned nothing, and none after it, the derivation having stopped there.
/// - `rotation`: the first of `ROTATIONS` from which the four couplings by the prior's census are
///   `balanced` (ADR-0065).
/// - `gain`: the first of `GAINS` whose frozen block on the prior's network is `calibrated`
///   (ADR-0066).
/// - `settled`: the window at which ADR-0055's criterion first holds over the lead-in,
///   `settled_within`, within `LEAD_IN_EXTENDED` windows (ADR-0077).
/// - `span`: the last tick a volley spike fell on in the gain's frozen block, `span_of`; none for
///   a block with no volley spike (ADR-0076).
/// - `least`: the least messages at the bound a tick, over that span, that leave a unit firing
///   once, at rest and at `EXTREME_STANDING`, `least_cancel_over` within `LEAST_SCAN`.
/// - `cancel`: the messages of the first candidate — the least at rest, the least at the extreme,
///   twice it — whose probe fires once and whose frozen block on the prior's network fires once
///   (`first_firing_once`, ADR-0076's pick).
/// - `frozen`: the frozen block from the settled image under that cancel, `[the stimulus fires
///   once, the sight at SEEN_MIN]` — the two measures every round since H-13 has stood on.
/// - `period`: the inhibitory rule's target period, `target_period` over the settled image's
///   spikes (ADR-0128).
/// - `window`: the shortest delay of any synapse the image carries, `shortest_delay` (ADR-0134).
/// - `critic`: ADR-0132's arithmetic for the stimulus's units, `critic_for`.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct Rules {
    rotation: Option<u32>,
    gain: Option<u32>,
    settled: Option<usize>,
    span: Option<u32>,
    least: [Option<u32>; 2],
    cancel: Option<u32>,
    frozen: Option<[bool; 2]>,
    period: Option<u32>,
    window: Option<u16>,
    critic: Option<ValueCritic>,
}

impl Rules {
    /// H-33's clause 0 (ADR-0165): every rule gave a value and the frozen block passed both
    /// measures.
    fn hold(&self) -> bool {
        self.rotation.is_some()
            && self.gain.is_some()
            && self.settled.is_some()
            && self.span.is_some()
            && self.least.iter().all(Option::is_some)
            && self.cancel.is_some()
            && self.frozen == Some([true, true])
            && self.period.is_some()
            && self.window.is_some()
            && self.critic.is_some()
    }
}

/// The constants the tree holds for the instrument's prior, seed 22, as what the rules return:
/// each a constant an earlier round derived by the rule beside it and pinned.
const RULES_1024: Rules = Rules {
    rotation: Some(ROTATION_1024),
    gain: Some(GAIN_1024),
    settled: SETTLED_AT_1024[SETTLED],
    span: Some(CANCEL_TICKS),
    least: [Some(CANCEL_ONCE_AT_REST), Some(CANCEL_AT_THE_EXTREME)],
    cancel: CANCEL_PICKED_1024,
    frozen: Some([true, true]),
    period: Some(TARGET_PERIOD_1024),
    window: Some(WINDOW_TICKS_1024),
    critic: Some(VALUED_CRITIC),
};

/// The rotation's rule (ADR-0065): the first rotation of `ROTATIONS`, from zero, at which the four
/// couplings `read` gives are `balanced`, with the couplings at every rotation scanned, the one
/// taken last; none when no rotation of the range is. A rotation that puts a stimulus on the
/// units the prior makes inhibitory reads a coupling of zero and so does not pass.
fn first_balanced(read: &dyn Fn(u32) -> [i64; 4]) -> (Option<u32>, Vec<[i64; 4]>) {
    let mut scanned = Vec::new();
    for rotation in 0..ROTATIONS {
        let couplings = read(rotation);
        scanned.push(couplings);
        if balanced(&couplings) {
            return (Some(rotation), scanned);
        }
    }
    (None, scanned)
}

/// The gain's rule (ADR-0066), `picked` over as many candidates as were run: the first of `GAINS`,
/// in their order, whose frozen block is `calibrated`; none when none of those run is.
fn first_calibrated(runs: &[(Block, u64)]) -> Option<u32> {
    GAINS
        .iter()
        .zip(runs.iter())
        .find(|(_, (block, _))| calibrated(block))
        .map(|(&gain, _)| gain)
}

/// The cancel's candidates over a span at a gain (ADR-0076), as counts of messages at the bound a
/// tick: the least that leaves a unit at rest firing once, the least that leaves a unit at
/// `EXTREME_STANDING` firing once, and twice the second; with the two least counts as the oracle
/// gave them. No candidates when either scan found none within `LEAST_SCAN`.
fn cancel_candidates(span: u32, gain: u32) -> ([Option<u32>; 2], Option<[u32; 3]>) {
    let least = [
        least_cancel_over(span, (0, 0), gain),
        least_cancel_over(span, EXTREME_STANDING, gain),
    ];
    let candidates = match least {
        [Some(rest), Some(extreme)] => Some([rest, extreme, extreme.saturating_mul(2)]),
        _ => None,
    };
    (least, candidates)
}

/// The cancel's pick (ADR-0076), `cancel_pick` over the candidates given and a stimulus set of
/// `len` units: the first candidate, in their order, whose probe passed and whose frozen block
/// fires once by ADR-0074's measure; none when none of those run does.
fn first_firing_once(
    len: u64,
    candidates: &[u32],
    probed: &[bool],
    runs: &[(Block, u64, Composition)],
) -> Option<u32> {
    candidates
        .iter()
        .zip(probed.iter())
        .zip(runs.iter())
        .find(|&((_, &probed), (block, _, composition))| {
            probed && fires_once_of(len, block, composition)
        })
        .map(|((&messages, _), _)| messages)
}

/// `quiet` as a rule that can return nothing: `exec` run without the drive until it is quiescent,
/// the ticks it took; none when it is still active after `QUIET_BOUND` ticks, where `quiet` fails
/// its test. A countdown, so it ends by construction.
fn quiet_within(exec: &mut Engine) -> Option<u64> {
    let mut ticks = 0u64;
    for _ in 0..QUIET_BOUND {
        if exec.is_quiescent() {
            return Some(ticks);
        }
        exec.tick();
        ticks = ticks.wrapping_add(1);
    }
    exec.is_quiescent().then_some(ticks)
}

/// The frozen block's two measures for a stimulus set of `len` units (ADR-0165's clause 0):
/// ADR-0074's `fires_once`, and the sight — the window after the volley holding more readout
/// spikes than the window before the injection in at least `SEEN_MIN` trials of the block.
fn frozen_measures(len: u64, block: &Block, composition: &Composition) -> [bool; 2] {
    [fires_once_of(len, block, composition), block.6 >= SEEN_MIN]
}

/// ADR-0132's arithmetic restated for a stimulus of `units` units (ADR-0167), with the split
/// ADR-0168 gives it past 64 units:
/// - the sum of the shift and the scale is the least at which one volley of `units` spikes moves
///   the value of the same volley by at most the task critic's thirty-second of the error,
///   `units × 32 ≤ 2^sum`, scanned from zero to `CRITIC_SUM_MAX`;
/// - the shift is the lesser of the sum less ADR-0132's scale and `SHIFT_HELD`, the largest shift
///   whose dead band is under one per cent of the reward;
/// - the scale is the sum less the shift.
///
/// None when no sum of the range fits, when the sum is below ADR-0132's scale, which is a
/// stimulus of no unit, and when the loader would refuse the constants. Up to 64 units the shift
/// is the sum less ADR-0132's scale and the scale is ADR-0132's, as ADR-0167 wrote the rule, and
/// for 33 to 64 units it is ADR-0132's own, a shift of 9 and a scale of 2. Past 64 units, where
/// the rule as ADR-0167 wrote it returned nothing — its shift's dead band a per cent of the
/// reward and more — the shift stays at 9 and the scale takes the rest: 9 and 3 for 65 to 128
/// units, 9 and 4 for 129 to 256.
fn critic_for(units: u32) -> Option<ValueCritic> {
    let step = u64::from(units).checked_shl(TASK_STEP_SHIFT)?;
    let sum =
        (0..=CRITIC_SUM_MAX).find(|&n| 1u64.checked_shl(n).is_some_and(|whole| step <= whole))?;
    let sum = u8::try_from(sum).ok()?;
    let shift = sum.checked_sub(SPLIT_SCALE)?.min(SHIFT_HELD);
    let critic = ValueCritic {
        shift,
        scale: sum.checked_sub(shift)?,
    };
    critic.is_valid().then_some(critic)
}

/// The excitatory sum outside the four couplings of an image: `image_outside` for any image, its
/// excitatory sum less its four couplings.
fn outside_image(couplings: &[[i64; 2]; 2], excitatory: i64) -> i64 {
    couplings
        .iter()
        .flatten()
        .fold(excitatory, |sum, &c| sum.saturating_sub(c))
}

// ------------------------------------------------------------ the criterion (ADR-0165)

/// H-33's verdict on one network (ADR-0165): clause 0, the rules derive a configuration; and,
/// where it holds and the arms ran, clauses 1 to 4, H-25's four by H-25's rules (`drawn_of`)
/// against the network's own image. `yes` is all five in both arms; a no names the clause, and
/// under clauses 1 to 4 the arm, as H-25's verdict names them.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Seeded {
    derived: bool,
    arms: Option<Drawn>,
    yes: bool,
}

/// A network's image for the clauses and its two arms' blocks: the image's four couplings, its
/// outside sum, and the blocks `[assignment first, mirrored first]`.
type SeededArms<'a> = (&'a [[i64; 2]; 2], i64, [&'a [Block]; 2]);

fn seeded(rules: &Rules, arms: Option<SeededArms<'_>>) -> Seeded {
    let derived = rules.hold();
    let arms = arms
        .filter(|_| derived)
        .map(|(couplings, outside, blocks)| drawn_of(couplings, outside, blocks));
    Seeded {
        derived,
        arms,
        yes: derived && arms.is_some_and(|verdict| verdict.yes),
    }
}

/// The step of ADR-0165's stopping rule the two networks' verdicts reach: 3, yes on both; 4, a no
/// on clause 0 on either; otherwise 5, a no on clause 4; otherwise 6, a no on clause 1 or 2;
/// otherwise 7, a no on clause 3 alone.
fn seeded_step(networks: &[Seeded; 2]) -> u8 {
    if networks.iter().all(|n| n.yes) {
        return 3;
    }
    if networks.iter().any(|n| !n.derived) {
        return 4;
    }
    let arms = || networks.iter().filter_map(|n| n.arms);
    if arms().any(|verdict| !verdict.held.iter().all(|&h| h)) {
        return 5;
    }
    if arms().any(|verdict| !verdict.learning.yes) {
        return 6;
    }
    7
}

// ----------------------------------------------------- the readings' shape (brief 067)

/// The selections of a frozen block by stimulus `[A, B]`: the trials that selected readout 0,
/// readout 1 and neither, each trial's selection the sign of its counts as the task makes it.
fn frozen_selections(counted: &[Counted]) -> [[u32; 3]; 2] {
    let mut splits = [[0u32; 3]; 2];
    for &(stimulus, counts) in counted {
        if let Some(into) = splits
            .get_mut(usize::from(stimulus))
            .and_then(|s| s.get_mut(selected(counts).map_or(2, usize::from)))
        {
            *into = into.saturating_add(1);
        }
    }
    splits
}

/// `couplings_course` against the image couplings given: the four couplings at each block's end
/// as fractions of the image's, in parts per ten thousand.
fn couplings_course_of(image: &[[i64; 2]; 2], blocks: &[Block]) -> Vec<[[i64; 2]; 2]> {
    blocks
        .iter()
        .map(|b| [0usize, 1].map(|s| [0usize, 1].map(|r| per_myriad(b.10[s][r], image[s][r]))))
        .collect()
}

/// The compositions of a run in one number: `fnv1a_64` over each block's own hash, as its two
/// `i32` words.
fn compositions_hash(compositions: &[Composition]) -> u64 {
    let words: Vec<i32> = compositions
        .iter()
        .flat_map(|c| [c.4 as i32, (c.4 >> 32) as i32])
        .collect();
    fnv1a_64(&words)
}

/// What an arm of H-33 reads of its run (brief 067), each by the rule H-25's arm reads it by,
/// against the network's own image: the correct trials of each mapping's last 128; the first
/// block past the couplings' bound; the block each mapping passes 40 of 64 in; the first block
/// that left the band; each stimulus's trials, correct trials and summed value over each
/// mapping's last 128; each mapping's highest coupling; the value's trough after each flip; each
/// mapping's trials by outcome; the blocks in which the stimulus fired once; whether the
/// inhibitory sum fell in every block; the reach by polarity over the four pairs; and the sums by
/// polarity after the run.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct SeededRead {
    correct: [u32; 4],
    over: Option<(usize, usize, usize)>,
    crossings: [Option<usize>; 4],
    left: Option<(usize, i64)>,
    stimulus_values: [[StimulusValue; 2]; 4],
    highest: [Option<Peak>; 4],
    troughs: [[i64; 2]; 3],
    tally: [[u32; 3]; 4],
    once: u32,
    falls: bool,
    reach: Reach,
    sums_after: (i64, i64),
}

// -------------------------------------------------------- the derivation (brief 067)

/// What a derivation makes where every rule gave a value and the frozen block passed: the
/// constants a rewarded run takes from the network, the gain, the settled image's sums by polarity
/// and its four couplings, the target period, the window, the critic, and two images — the
/// settled image frozen, and H-25's image of this network, the one each arm decodes.
struct Made {
    derived: Derived,
    gain: u32,
    sums: (i64, i64),
    couplings: [[i64; 2]; 2],
    period: u32,
    window: u16,
    critic: ValueCritic,
    windowed: Vec<u8>,
}

/// A derivation on one prior (brief 067): what each rule returned, and the tables it was read
/// from, in the derivations' order. A table after the rule that returned nothing is empty.
/// - `scanned`: the four couplings by the prior's census at each rotation scanned.
/// - `prior_sums`: the prior's sums by polarity, before any window.
/// - `calibrations`: the frozen block and its trace on the prior's network at each gain tried.
/// - `census`, `synapses`: of the picked gain's block, the volley's spikes by tick and the
///   synapses from each stimulus set onto each readout set.
/// - `probes`, `cancelled`: per candidate tried, the ticks a unit at rest fires on through the
///   task, and the frozen block on the prior's network with its trace and composition.
/// - `lead_in`, `quiet`: the settling's windows, and the quiet run's ticks and sums.
/// - `frozen`, `counted`, `frozen_census`: the frozen block from the settled image under the
///   picked cancel, with its trace and composition; every trial's counts; the volley's census.
/// - `target_lead_in`: the settled image's spikes by window under the reference drive.
/// - `crcs`: the CRC-64 of the settled image frozen, and of it with the inhibitory baseline, the
///   signed gate, the target period, the critic and the window written, each onto the last.
/// - `crcs_read` (ADR-0180): the same six with each image's header written back to
///   `DERIVED_READ_FORMAT` and resealed, the format H-33 and H-34 read theirs at.
/// - `crcs_ruled` (ADR-0189): the same six written back to `RULED_READ_FORMAT`, the format H-38
///   and H-39 read theirs at.
/// - `crcs_read_target` (ADR-0194): the same six written back to `READ_TARGET_FORMAT`, the format
///   H-40 read its at.
/// - `crcs_both_targets` (ADR-0202): the same six written back to `BOTH_TARGETS_FORMAT`, the
///   format H-41 read its at.
/// - `couplings`: the settled image's four couplings.
/// - `read` (ADR-0190): under a read of the target, what the read left after the lead-in — under
///   way, refused, or none — and the period and the count the engine then held; none without a
///   read.
/// - `istdp` (ADR-0195): under the read's flag for the inhibitory target (ADR-0194), the
///   inhibitory rule's period the engine held after the lead-in, which the image carries; none
///   without the flag.
/// - `probe` (ADR-0203): under the probe of the step (ADR-0202), the step the engine held after
///   the lead-in, which the image carries — the probe's, or the configuration's where the probe
///   ended refused; none without the probe.
/// - `carried`, `after_frozen` (brief 071): the gain and the estimate the settled image carries,
///   and the two as the frozen block left them; with the gain held the gain is the gain's rule's
///   in both.
#[derive(Default)]
struct Derivation {
    rules: Rules,
    scanned: Vec<[i64; 4]>,
    prior_sums: (i64, i64),
    calibrations: Vec<(Block, u64)>,
    census: Vec<(u32, u64)>,
    synapses: [[u32; 2]; 2],
    probes: Vec<Vec<u32>>,
    cancelled: Vec<(Block, u64, Composition)>,
    lead_in: Vec<LeadInWindow>,
    quiet: Option<(u64, (i64, i64))>,
    carried: Option<(u32, u32)>,
    after_frozen: Option<(u32, u32)>,
    frozen: Option<(Block, u64, Composition)>,
    counted: Vec<Counted>,
    frozen_census: Vec<(u32, u64)>,
    target_lead_in: Vec<u64>,
    crcs: Option<[u64; 6]>,
    crcs_read: Option<[u64; 6]>,
    crcs_ruled: Option<[u64; 6]>,
    crcs_read_target: Option<[u64; 6]>,
    crcs_both_targets: Option<[u64; 6]>,
    couplings: Option<[[i64; 2]; 2]>,
    made: Option<Made>,
    read: Option<ReadMade>,
    istdp: Option<u32>,
    probe: Option<u16>,
}

/// The format H-33's and H-34's derivations read their images at (ADR-0167, ADR-0169): 21. Since
/// ADR-0180 moved the format to 22 a derivation is held to those rounds' CRCs through each image
/// with its header's version written back to it and the header resealed (`with_version`), so
/// that every byte of an image but the version and the seal is the image the round read (as
/// ADR-0095).
const DERIVED_READ_FORMAT: u32 = 21;

/// The format H-38's and H-39's derivations read their images at (ADR-0181, ADR-0183): 22. Since
/// ADR-0189 moved the format to 23 a derivation under the rate's rule is held to those rounds'
/// CRCs through each image with its header's version written back to it and the header resealed,
/// as `DERIVED_READ_FORMAT` holds H-33's and H-34's.
const RULED_READ_FORMAT: u32 = 22;

/// The format H-40's derivations read their images at (ADR-0190): 23. Since ADR-0194 moved the
/// format to 24 a derivation under the read is held to that round's CRCs through each image with
/// its header's version written back to it and the header resealed, as `RULED_READ_FORMAT` holds
/// H-38's and H-39's.
const READ_TARGET_FORMAT: u32 = 23;

/// The format H-41's derivations read their images at (ADR-0195): 24. Since ADR-0202 moved the
/// format to 25 a derivation under both targets is held to that round's CRCs through each image
/// with its header's version written back to it and the header resealed, as `READ_TARGET_FORMAT`
/// holds H-40's.
const BOTH_TARGETS_FORMAT: u32 = 24;

/// The configuration H-25 ran under, derived on ADR-0044's prior at 1 024 units from `seed`
/// (ADR-0165, ADR-0167; `derive_at` with the size, since brief 068): each constant by the rule
/// that derived it on the instrument's prior, in
/// ADR-0165's order, nothing carried over from another network, and the derivation stopped at the
/// first rule that returns nothing.
/// 1. The rotation: `first_balanced` over the prior's census.
/// 2. The gain: the calibration's frozen block — the prior's network at the gain, the baseline
///    zero, F-46's stimulus with no cancel, sixty-four trials — at each of `GAINS` in order until
///    one is `calibrated`. The block's volley census is ADR-0072's composition's.
/// 3. The settled network: `candidate_from` at the gain under the drive alone until
///    `settled_within` holds or `LEAD_IN_EXTENDED` windows have run; then the quiet run and the
///    image with the baseline at zero.
/// 4. The cancel: the offset the refractory window and one; the span the census's; the candidates
///    `cancel_candidates`; each in order probed on a unit at rest and run for a frozen block on the
///    prior's network at the gain, until one fires once. Then the frozen block from the settled
///    image under it, read by `frozen_measures`.
/// 5. The target period: `target_period` over the settled image frozen under the reference drive
///    for `TARGET_LEAD_IN_TICKS`.
/// 6. The critic's window, `shortest_delay` of the image; and the critic, `critic_for` the
///    stimulus set's units.
///
/// Then H-25's image is written as H-25's arms write it: the settled image frozen, with the
/// inhibitory baseline, the signed gate, the target period, the critic and the window, each
/// change shown to be the only one where a masked check exists for it.
fn derive(seed: u64, name: &str) -> Derivation {
    derive_at(1024, seed, name)
}

/// `derive` at `units` (ADR-0168, brief 068): the same rules in the same order, with the size
/// given wherever `derive` wrote 1 024 — the prior, every configuration, the geometry, the drive,
/// the target period's exposure and every image's decoding. The stimulus set's units, which the
/// frozen block's measures and the critic's rule read, are the geometry's at that size. `derive`
/// calls it with 1 024, so on a network at 1 024 units it is the derivation it was.
fn derive_at(units: u32, seed: u64, name: &str) -> Derivation {
    derive_under(units, seed, &GAIN_HELD, name)
}

/// How a derivation settles its network (ADR-0177, brief 071; ADR-0181, brief 072): the
/// controller's step its lead-in runs under and its image carries; whether the settled network's
/// rule reads the gains beside the excitatory sums; the lead-in's bound in windows; the rate's
/// target, a period in ticks, its lead-in runs under and its image carries, zero while unset
/// (ADR-0180); and whether the rule reads, beside the sums, the gain's mean over sixteen windows
/// in each window's gain's place (ADR-0178). Since ADR-0190, the span of a read of the rate's
/// target its lead-in runs under (ADR-0189), zero while unset: the settled network's rule is
/// then read over the windows after the read, and settles only where the read made a target.
/// Since ADR-0195, whether that read sets the inhibitory rule's target as well (ADR-0194), unset
/// in every settling the tree held before. Since ADR-0203, whether the read is followed by the
/// probe of the step (ADR-0202), unset in every settling the tree held before: the settled
/// network's rule is then read over the windows after the probe.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Settling {
    step: u16,
    gains: bool,
    bound: u64,
    target: u32,
    mean: bool,
    read: u8,
    inhibitory: bool,
    probe: bool,
}

/// The gain held, every derivation's settling to brief 070: the step zero, ADR-0077's rule over
/// the sums, within `LEAD_IN_EXTENDED` windows.
const GAIN_HELD: Settling = Settling {
    step: BACKGROUNDS[SETTLED],
    gains: false,
    bound: LEAD_IN_EXTENDED,
    target: 0,
    mean: false,
    read: 0,
    inhibitory: false,
    probe: false,
};

/// ADR-0077's second candidate as a settling: the controller at its step of an eighth, the
/// lead-in held to the sums alone within `LEAD_IN_EXTENDED` windows, as ADR-0077 ran it.
const AT_AN_EIGHTH: Settling = Settling {
    step: CONTROL_STEP_EIGHTH,
    gains: false,
    bound: LEAD_IN_EXTENDED,
    target: 0,
    mean: false,
    read: 0,
    inhibitory: false,
    probe: false,
};

/// The settled network's rule under a controller's step (ADR-0175, ADR-0177): the first window at
/// which ADR-0055's criterion holds over the excitatory sums and over the gains, both at that
/// window; none when no window of the two series is. `priors` are the excitatory sum and the gain
/// before the first window. With the gain held every gain is the prior's, the criterion over the
/// gains holds at every window from the sixteenth, and the rule is `settled_within` over the sums.
fn settled_in_both(priors: (i64, i64), sums: &[i64], gains: &[i64]) -> Option<usize> {
    (SETTLED_WINDOWS..=sums.len().min(gains.len()))
        .find(|&window| settled_in(priors.0, sums, window) && settled_in(priors.1, gains, window))
}

/// The gains of a lead-in table, each as its window's regulation left it.
fn lead_in_gains(table: &[LeadInWindow]) -> Vec<i64> {
    table.iter().map(|w| i64::from(w.5)).collect()
}

impl Settling {
    /// The settled network's rule over a lead-in's table, `prior` the excitatory sum and `gain`
    /// the gain before the first window: `settled_within` over the sums; or, where the rule
    /// reads the gains, `settled_in_both`; or, where it reads the gain's mean,
    /// `settled_in_mean`. Under a read of the target (ADR-0190) the same rule over the windows
    /// after the read, the sum and the gain its last window left in the prior's place, the window
    /// counted from the lead-in's first: no window of the read is one the rule moved the gain in,
    /// so none settles a network under it. Whether the read made a target is the derivation's to
    /// read from the engine (`derive_under`). Under the probe (ADR-0203) the windows read past are
    /// the read's and the probe's sixteen, the probe's last window's sum and gain in the prior's
    /// place: no window of the probe is one the rule moved the gain in either.
    fn settled(&self, prior: i64, gain: u32, table: &[LeadInWindow]) -> Option<usize> {
        let probe = if self.probe { PROBE_WINDOWS } else { 0 };
        let span = usize::from(self.read).saturating_add(probe);
        let Some(last) = span.checked_sub(1) else {
            return self.settled_over(prior, gain, table);
        };
        let held = table.get(last)?;
        self.settled_over(held.3, held.5, table.get(span..)?)
            .map(|window| window.saturating_add(span))
    }

    /// `settled`'s rule over a table read whole, from `prior` and `gain`.
    fn settled_over(&self, prior: i64, gain: u32, table: &[LeadInWindow]) -> Option<usize> {
        let sums = lead_in_sums(table);
        if self.mean {
            settled_in_mean(prior, &sums, &lead_in_gains(table))
        } else if self.gains {
            settled_in_both((prior, i64::from(gain)), &sums, &lead_in_gains(table))
        } else {
            settled_within(prior, &sums)
        }
    }
}

/// Shuts a derivation's settling engine down and holds every worker's report to no entry dropped.
fn undropped(exec: Engine, name: &str) {
    let reports = exec.shutdown();
    assert!(
        !reports.is_empty() && reports.iter().all(|r| r.dropped == 0),
        "{name}: no worker dropped an entry through the lead-in"
    );
}

/// The candidate's executor under a settling (ADR-0181): `candidate_from` at the settling's step,
/// with the settling's rate's target in its configuration, which `at_gain` writes into the image
/// it reloads from, so the engine carries it; since ADR-0190 its read of the target, begun, the
/// same way. With the target and the read unset the configuration is `candidate_from`'s field
/// for field. Since ADR-0195 the read's flag for the inhibitory target (ADR-0194) too, which the
/// image carries beside the read under way; and since ADR-0203 the probe's flag (ADR-0202), the
/// same way.
fn candidate_under(p: &Prior, units: u32, gain: u32, settling: &Settling) -> Engine {
    let cfg = Config {
        control_step_q0_16: settling.step,
        rate_target_period_ticks: settling.target,
        rate_read_windows: settling.read,
        istdp_target_read: settling.inhibitory,
        step_probe: settling.probe,
        ..config(units, 2, BASELINE_Q16)
    };
    let exec = at_gain(p, cfg, gain);
    assert_eq!(
        (
            exec.homeostasis().synaptic_gain_q16,
            exec.homeostasis().control_step_q0_16,
            exec.rate_target_period_ticks(),
            exec.modulation_baseline_q16(),
            exec.target_read()
        ),
        (
            gain,
            settling.step,
            settling.target,
            BASELINE_Q16,
            (settling.read > 0).then_some(TargetRead::Reading {
                left: settling.read,
                sum: 0
            })
        ),
        "the candidate carries the gain, the step, the rate's target, the baseline and the read"
    );
    assert_eq!(
        (exec.istdp_target_read(), exec.istdp_target_period_ticks()),
        (settling.inhibitory, ISTDP_TARGET_PERIOD_TICKS),
        "the candidate carries the read's flag, and the inhibitory rule's default period"
    );
    assert_eq!(
        exec.step_probe(),
        settling.probe,
        "the candidate carries the probe's flag"
    );
    exec
}

/// `derive_at` under a settling (ADR-0177, brief 071): the same rules in the same order, with the
/// controller's step where `derive_at` wrote `BACKGROUNDS[SETTLED]` — in the candidate's record
/// and in the image, which carries it through the frozen block, the target's lead-in and every
/// image written from it — and the settled network's rule and bound the settling's. Since
/// ADR-0181 the settling's rate's target is carried the same way, by the same images; with it
/// unset the candidate is the one it was. The rules
/// before the settled network do not read the step, and the cancel is derived on the prior's
/// network at the gain's rule's gain, as it is. The gain the image carries is the one the
/// lead-in's regulation left; with the step at zero it is asserted the gain's rule's. `derive_at`
/// calls it with `GAIN_HELD`, so every derivation of the tree is the derivation it was. Since
/// ADR-0190 the settling's read of the target is carried the same way: the derivation records
/// what the read left, the network settles only where it made a target, and the image carries
/// the period it made and no read. Since ADR-0195 the read's flag for the inhibitory target the
/// same way: the derivation records the inhibitory period the engine held after the lead-in
/// (`Derivation::istdp`), the image carries it, and the target period's rule, step 5, is still
/// read over the frozen copy, a reading beside it; with the flag unset every derivation is the
/// one it was. Since ADR-0203 the probe's flag the same way: the derivation records the step the
/// engine held after the lead-in (`Derivation::probe`), which the image carries in the
/// settling's step's place, and the network settles only where the probe made a step.
fn derive_under(units: u32, seed: u64, settling: &Settling, name: &str) -> Derivation {
    let p = prior_seeded(units, seed);
    let mut d = Derivation::default();
    // 1. The rotation, by the prior's census: the couplings do not read the gain.
    let laid = at_gain(&p, config(units, 1, 0), GAINS[0]);
    d.prior_sums = weights_by_polarity(&laid);
    let (rotation, scanned) =
        first_balanced(&|rotation| couplings(&laid, &geometry(units, rotation)));
    d.scanned = scanned;
    d.rules.rotation = rotation;
    let Some(rotation) = rotation else {
        return d;
    };
    let sets = geometry(units, rotation);
    let len = sets[0].len();
    assert_eq!(sets[1].len(), len, "{name}: two stimuli of one size");
    // 2. The gain, and with the picked gain's block its census and its synapses.
    let mut census_ticks: Vec<u64> = Vec::new();
    for &gain in &GAINS {
        let mut exec = at_gain(&p, config(units, 2, 0), gain);
        assert_eq!(exec.homeostasis().synaptic_gain_q16, gain);
        let (blocks, trace, _, counts, _, volley_ticks) =
            compose_on_over(sets, &mut exec, SHAPE_F46, None, units, BLOCK);
        let block = *blocks.first().expect("a block of the calibration");
        d.calibrations.push((block, trace));
        if calibrated(&block) {
            d.synapses = counts;
            census_ticks = volley_ticks;
            break;
        }
    }
    d.rules.gain = first_calibrated(&d.calibrations);
    let Some(gain) = d.rules.gain else {
        return d;
    };
    d.census = census_of(&census_ticks);
    // 3. The settled network and its image.
    let mut exec = candidate_under(&p, units, gain, settling);
    assert_eq!(
        weights_by_polarity(&exec),
        d.prior_sums,
        "{name}: the prior"
    );
    let prior_sum = d.prior_sums.1;
    d.lead_in = lead_in_until(
        [sets[2], sets[3]],
        &mut exec,
        units,
        settling.bound,
        &|table| settling.settled(prior_sum, gain, table).is_some(),
    );
    d.rules.settled = settling.settled(prior_sum, gain, &d.lead_in);
    // Under a read (ADR-0190): what it left, and a network settled only where it made a target.
    if settling.read > 0 {
        d.read = Some((
            exec.target_read(),
            exec.rate_target_period_ticks(),
            exec.rate_target_per_window(),
        ));
        if exec.target_read().is_some() {
            d.rules.settled = None;
        }
    }
    // Under the read's flag (ADR-0195): the inhibitory period the engine then held.
    if settling.inhibitory {
        d.istdp = Some(exec.istdp_target_period_ticks());
    }
    // Under the probe (ADR-0203): the step the engine then held. A probe under way or refused is
    // a read not ended in a target, so the network is not settled (above).
    if settling.probe {
        d.probe = Some(exec.homeostasis().control_step_q0_16);
    }
    if d.rules.settled.is_none() {
        undropped(exec, name);
        return d;
    }
    let Some(ticks) = quiet_within(&mut exec) else {
        // The settled network did not fall quiet, so no image can be written from it: the
        // settling's rule gave no network to stand on.
        d.rules.settled = None;
        undropped(exec, name);
        return d;
    };
    let sums = weights_by_polarity(&exec);
    d.quiet = Some((ticks, sums));
    // The gain the image carries: the gain's rule's with the gain held, and under a step the one
    // the lead-in's regulation left.
    let carried = exec.homeostasis().synaptic_gain_q16;
    if settling.step == 0 {
        assert_eq!(carried, gain, "{name}: the gain is held");
    }
    d.carried = Some((carried, exec.homeostasis().branching_ratio_q16));
    let zero = frozen_image(&exec);
    {
        // The rate's target the image carries: the settling's, or under a read the one it made.
        let target = d.read.map_or(settling.target, |(_, period, _)| period);
        let frozen = frozen_from(&zero, units);
        assert_eq!(
            (
                weights_by_polarity(&frozen),
                frozen.homeostasis().synaptic_gain_q16,
                frozen.homeostasis().control_step_q0_16,
                frozen.rate_target_period_ticks(),
                frozen.target_read(),
                frozen.ticks()
            ),
            (
                sums,
                carried,
                d.probe.unwrap_or(settling.step),
                target,
                None,
                exec.ticks()
            ),
            "{name}: the image carries the weights, the gain, the step, the rate's target and the clock, and no read"
        );
        assert_eq!(
            (
                frozen.istdp_target_period_ticks(),
                frozen.istdp_target_read(),
                frozen.step_probe()
            ),
            (d.istdp.unwrap_or(ISTDP_TARGET_PERIOD_TICKS), false, false),
            "{name}: the image carries the inhibitory period the lead-in left, and no flag"
        );
    }
    undropped(exec, name);
    // 4. The cancel, and the frozen block from the settled image under it.
    let span = span_of(&d.census);
    d.rules.span = (span > 0).then_some(span);
    if d.rules.span.is_none() {
        return d;
    }
    let (least, candidates) = cancel_candidates(span, gain);
    d.rules.least = least;
    let Some(candidates) = candidates else {
        return d;
    };
    let mut probed: Vec<bool> = Vec::new();
    for &messages in &candidates {
        let cancel = cancel_over(span, messages);
        let probe = probe_task_on(&p, gain, SHAPE_F46, Some(cancel));
        probed.push(probe.len() == 1);
        d.probes.push(probe);
        let mut exec = at_gain(&p, config(units, 2, 0), gain);
        let (blocks, trace, trials, counts, _, _) =
            compose_on_over(sets, &mut exec, SHAPE_F46, Some(cancel), units, BLOCK);
        assert_eq!(counts, d.synapses, "{name}: the same synapses");
        let block = *blocks.first().expect("a block of the candidate");
        d.cancelled.push((block, trace, composition(&trials)));
        if first_firing_once(len, &candidates, &probed, &d.cancelled).is_some() {
            break;
        }
    }
    d.rules.cancel = first_firing_once(len, &candidates, &probed, &d.cancelled);
    let Some(messages) = d.rules.cancel else {
        return d;
    };
    let cancel = cancel_over(span, messages);
    {
        let mut frozen = frozen_from(&zero, units);
        let (blocks, trace, trials, counts, counted, volley_ticks) =
            compose_on_over(sets, &mut frozen, SHAPE_F46, Some(cancel), units, BLOCK);
        assert_eq!(counts, d.synapses, "{name}: the settled network's synapses");
        let block = *blocks.first().expect("a frozen block");
        let composed = composition(&trials);
        d.rules.frozen = Some(frozen_measures(len, &block, &composed));
        d.frozen = Some((block, trace, composed));
        d.counted = counted;
        d.frozen_census = census_of(&volley_ticks);
        d.after_frozen = Some((
            frozen.homeostasis().synaptic_gain_q16,
            frozen.homeostasis().branching_ratio_q16,
        ));
    }
    if d.rules.frozen != Some([true, true]) {
        return d;
    }
    // 5. The target period, on the settled image frozen; under the read's flag (ADR-0195) a
    // reading beside the period the image carries, which is the read's.
    let carried_period = d.istdp.unwrap_or(ISTDP_TARGET_PERIOD_TICKS);
    let windows = target_lead_in_under(&zero, units, carried_period);
    d.target_lead_in = windows.iter().map(|w| spikes_of(w)).collect();
    let period = target_period(
        u64::from(units),
        TARGET_LEAD_IN_TICKS,
        spikes_of(&summed(&windows)),
    );
    d.rules.period = Some(period);
    let period = d.istdp.unwrap_or(period);
    // H-20's image of this network, then H-21's.
    let inhibited = inhibited_image(&zero);
    let signed = signed_image(&inhibited);
    let targeted = targeted_image(&signed, period);
    assert!(
        only_the_target(&signed, &targeted),
        "{name}: the target period's bytes and the seal, and nothing else"
    );
    // 6. The critic's window and the critic.
    d.rules.window = shortest_delay(signed_from(&targeted, units).blocks());
    let Some(window) = d.rules.window else {
        return d;
    };
    d.rules.critic = u32::try_from(len).ok().and_then(critic_for);
    let Some(critic) = d.rules.critic else {
        return d;
    };
    let valued = valued_image(&targeted, critic);
    assert!(
        only_the_critic(&targeted, &valued),
        "{name}: the critic's bytes and the seal, and nothing else"
    );
    let windowed = with_window_bytes(&valued, window);
    assert!(
        only_the_window(&valued, &windowed),
        "{name}: the window's bytes and the seal, and nothing else"
    );
    let images = [&zero, &inhibited, &signed, &targeted, &valued, &windowed];
    d.crcs = Some(images.map(|image| crc64(image)));
    d.crcs_read = Some(images.map(|image| crc64(&with_version(image, DERIVED_READ_FORMAT))));
    d.crcs_ruled = Some(images.map(|image| crc64(&with_version(image, RULED_READ_FORMAT))));
    d.crcs_read_target = Some(images.map(|image| crc64(&with_version(image, READ_TARGET_FORMAT))));
    d.crcs_both_targets =
        Some(images.map(|image| crc64(&with_version(image, BOTH_TARGETS_FORMAT))));
    let image_couplings = pair_couplings(&signed_from(&windowed, units), &sets);
    d.couplings = Some(image_couplings);
    d.made = Some(Made {
        derived: Derived {
            rotation,
            cancel,
            synapses: d.synapses,
        },
        gain: carried,
        sums,
        couplings: image_couplings,
        period,
        window,
        critic,
        windowed,
    });
    d
}

/// Dumps a derivation whole, as it is pinned, before anything of it is held; then each constant
/// beside seed 22's and the frozen block's readings beside seed 22's.
fn dump_derivation(name: &str, d: &Derivation) {
    eprintln!("DUMP {name} PIN rules {:?}", d.rules);
    eprintln!("DUMP {name} PIN scanned {:?}", d.scanned);
    eprintln!("DUMP {name} PIN prior sums {:?}", d.prior_sums);
    eprintln!("DUMP {name} PIN calibrations {:?}", d.calibrations);
    eprintln!("DUMP {name} PIN census {:?}", d.census);
    eprintln!("DUMP {name} PIN synapses {:?}", d.synapses);
    eprintln!("DUMP {name} PIN probes {:?}", d.probes);
    eprintln!("DUMP {name} PIN cancelled {:?}", d.cancelled);
    eprintln!("DUMP {name} PIN lead-in {:?}", d.lead_in);
    eprintln!("DUMP {name} PIN read made {:?}", d.read);
    eprintln!("DUMP {name} PIN quiet {:?}", d.quiet);
    eprintln!("DUMP {name} PIN frozen {:?}", d.frozen);
    eprintln!("DUMP {name} PIN counted {:?}", d.counted);
    eprintln!("DUMP {name} PIN frozen census {:?}", d.frozen_census);
    eprintln!("DUMP {name} PIN target lead-in {:?}", d.target_lead_in);
    eprintln!(
        "DUMP {name} PIN crcs {:?}",
        d.crcs.map(|crcs| crcs.map(|crc| format!("{crc:#018x}")))
    );
    eprintln!(
        "DUMP {name} crcs with the version written back to {DERIVED_READ_FORMAT} {:?}",
        d.crcs_read
            .map(|crcs| crcs.map(|crc| format!("{crc:#018x}")))
    );
    eprintln!(
        "DUMP {name} crcs with the version written back to {RULED_READ_FORMAT} {:?}",
        d.crcs_ruled
            .map(|crcs| crcs.map(|crc| format!("{crc:#018x}")))
    );
    eprintln!(
        "DUMP {name} crcs with the version written back to {READ_TARGET_FORMAT} {:?}",
        d.crcs_read_target
            .map(|crcs| crcs.map(|crc| format!("{crc:#018x}")))
    );
    eprintln!(
        "DUMP {name} crcs with the version written back to {BOTH_TARGETS_FORMAT} {:?}",
        d.crcs_both_targets
            .map(|crcs| crcs.map(|crc| format!("{crc:#018x}")))
    );
    eprintln!("DUMP {name} PIN couplings {:?}", d.couplings);
    eprintln!(
        "DUMP {name} the rules returned {:?} beside seed 22's {RULES_1024:?}; clause 0 {}",
        d.rules,
        d.rules.hold()
    );
    eprintln!(
        "DUMP {name} lead-in windows {} beside seed 22's {}; prior sums {:?} beside {PRIOR_SUMS_1024:?}; quiet {:?} beside {:?}; synapses {:?} beside {SYNAPSES_1024:?}; image couplings {:?} beside {IMAGE_COUPLINGS_1024:?}; target lead-in {:?} beside {TARGET_LEAD_IN_1024:?}",
        d.lead_in.len(),
        BACKGROUND_LEAD_IN_1024[SETTLED].len(),
        d.prior_sums,
        d.quiet,
        QUIET_1024[SETTLED],
        d.synapses,
        d.couplings,
        d.target_lead_in
    );
    let (block_22, _, composed_22) = &BACKGROUND_1024[SETTLED];
    eprintln!(
        "DUMP {name} frozen block, the readouts' spikes [after, before, seen] {:?}, the stimulus's after the opening {:?}, the sign {:?}, the sight with each readout above {:?}, the selections [A, B] of [readout 0, readout 1, tie] {:?}; beside seed 22's {:?}, {}, {}, {}, {:?}",
        d.frozen.map(|(block, _, _)| measure(&block)),
        d.frozen.map(|(_, _, composed)| composed.2[2][1]),
        d.frozen.map(|(_, _, composed)| composed.3),
        d.frozen.map(|(block, _, _)| calibrated(&block)),
        frozen_selections(&d.counted),
        measure(block_22),
        composed_22.2[2][1],
        composed_22.3,
        calibrated(block_22),
        frozen_selections(&BACKGROUND_COUNTED_1024[SETTLED])
    );
    eprintln!(
        "DUMP {name} frozen block's margins, [A, B] of [the two counts' difference summed in magnitude, the two counts summed] {:?}; beside seed 22's at 1 024 units {:?}, seed 23's {:?} and seed 24's {:?}",
        frozen_margins(&d.counted),
        frozen_margins(&BACKGROUND_COUNTED_1024[SETTLED]),
        frozen_margins(FROZEN_COUNTED_SEEDED[0]),
        frozen_margins(FROZEN_COUNTED_SEEDED[1])
    );
    eprintln!(
        "DUMP {name} beside seeds 23 and 24 at 1 024 units, the rules returned {RULES_SEEDED:?}"
    );
}

/// The tables a derivation on one network is held to, pinned from its one run (brief 067; gathered
/// per network by brief 068, so that a network of another size is held as one of another seed
/// is): what each rule returned, and every table it was read from, as `Derivation` holds them.
#[derive(Clone, Copy)]
struct DerivationPins {
    rules: Option<Rules>,
    scanned: &'static [[i64; 4]],
    prior_sums: (i64, i64),
    calibrations: &'static [(Block, u64)],
    census: &'static [(u32, u64)],
    synapses: [[u32; 2]; 2],
    probes: &'static [&'static [u32]],
    cancelled: &'static [(Block, u64, Composition)],
    lead_in: &'static [LeadInWindow],
    quiet: Option<(u64, (i64, i64))>,
    frozen: Option<(Block, u64, Composition)>,
    counted: &'static [Counted],
    frozen_census: &'static [(u32, u64)],
    target_lead_in: &'static [u64],
    crcs: Option<[u64; 6]>,
    couplings: Option<[[i64; 2]; 2]>,
}

/// The tables one arm's run is held to, pinned from its one run: by block the sight's blocks, the
/// earned blocks, the engine's value and the drawn sources; in one number each the accuracy
/// sequence, the compositions, every trial's reading, every trial's value and every trial's drawn
/// sources; the readings as written; the critic's reading (brief 068), none where no table
/// of it is written; and the arm's reading by H-28's rules with brief 070's beside it
/// (`ArmRead`, ADR-0174), none where none is written.
#[derive(Clone, Copy)]
struct ArmPins {
    blocks: &'static [Block],
    trace: u64,
    composed: u64,
    earned: &'static [EarnedBlock],
    read: u64,
    values: &'static [ValueBlock],
    value_hash: u64,
    sourced: &'static [Sourced],
    sources_hash: u64,
    readings: Option<SeededRead>,
    critic: Option<CriticRead>,
    whole: Option<ArmRead>,
}

/// A network a derivation and its two arms are run on (brief 068): its size, its prior's seed,
/// the name its dumps carry, and its pinned tables. H-33's are the two of `SEEDS` at 1 024 units
/// (`seeded_site`); H-34's the two of `TWICE_SEEDS` at `TWICE_SIZE` (`twice_site`).
struct Site {
    units: u32,
    seed: u64,
    name: String,
    derivation: DerivationPins,
    arms: [ArmPins; 2],
}

/// H-33's network of index `n` in `SEEDS`, at 1 024 units, with the tables its round pinned. The
/// critic's reading is brief 068's, read at this size beside H-34's.
fn seeded_site(n: usize) -> Site {
    let seed = SEEDS[n];
    Site {
        units: 1024,
        seed,
        name: format!("seeded{seed}"),
        derivation: DerivationPins {
            rules: RULES_SEEDED[n],
            scanned: SCANNED_SEEDED[n],
            prior_sums: PRIOR_SUMS_SEEDED[n],
            calibrations: CALIBRATIONS_SEEDED[n],
            census: CENSUS_SEEDED[n],
            synapses: SYNAPSES_SEEDED[n],
            probes: PROBES_SEEDED[n],
            cancelled: CANCELLED_SEEDED[n],
            lead_in: LEAD_IN_SEEDED[n],
            quiet: QUIET_SEEDED[n],
            frozen: FROZEN_SEEDED[n],
            counted: FROZEN_COUNTED_SEEDED[n],
            frozen_census: FROZEN_CENSUS_SEEDED[n],
            target_lead_in: TARGET_LEAD_IN_SEEDED[n],
            crcs: CRCS_SEEDED[n],
            couplings: COUPLINGS_SEEDED[n],
        },
        arms: [0usize, 1].map(|k| ArmPins {
            blocks: SEEDED_BLOCKS[n][k],
            trace: SEEDED_TRACES[n][k],
            composed: SEEDED_COMPOSED[n][k],
            earned: SEEDED_EARNED[n][k],
            read: SEEDED_READ[n][k],
            values: SEEDED_VALUES[n][k],
            value_hash: SEEDED_VALUE_HASH[n][k],
            sourced: SEEDED_SOURCED[n][k],
            sources_hash: SEEDED_SOURCES_HASH[n][k],
            readings: SEEDED_READINGS[n][k],
            critic: SEEDED_CRITIC[n][k],
            whole: SEEDED_WHOLE[n][k],
        }),
    }
}

/// Holds a derivation to a network's pinned tables: what each rule returned, and every table it
/// was read from. On a network no earlier round ran on there is no table from another run to hold
/// a derivation to: what holds it is the rule, run again, and the first run's tables pinned,
/// which the weekly run reproduces.
fn derivation_held(name: &str, pins: &DerivationPins, d: &Derivation) {
    assert_eq!(Some(d.rules), pins.rules, "{name}: what each rule returned");
    assert_eq!(
        d.scanned.as_slice(),
        pins.scanned,
        "{name}: the couplings at each rotation scanned"
    );
    assert_eq!(d.prior_sums, pins.prior_sums, "{name}: the prior's sums");
    assert_eq!(
        d.calibrations.as_slice(),
        pins.calibrations,
        "{name}: the calibration's blocks"
    );
    assert_eq!(
        d.census.as_slice(),
        pins.census,
        "{name}: the volley's census"
    );
    assert_eq!(d.synapses, pins.synapses, "{name}: the synapses");
    assert_eq!(
        d.probes.iter().map(Vec::as_slice).collect::<Vec<&[u32]>>(),
        pins.probes,
        "{name}: the probes"
    );
    assert_eq!(
        d.cancelled.as_slice(),
        pins.cancelled,
        "{name}: the candidates' frozen blocks"
    );
    assert_eq!(d.lead_in.as_slice(), pins.lead_in, "{name}: the lead-in");
    assert_eq!(d.quiet, pins.quiet, "{name}: the quiet run");
    assert_eq!(d.frozen, pins.frozen, "{name}: the frozen block");
    assert_eq!(
        d.counted.as_slice(),
        pins.counted,
        "{name}: the frozen block's counts"
    );
    assert_eq!(
        d.frozen_census.as_slice(),
        pins.frozen_census,
        "{name}: the frozen block's census"
    );
    assert_eq!(
        d.target_lead_in.as_slice(),
        pins.target_lead_in,
        "{name}: the target's lead-in"
    );
    assert_eq!(
        d.crcs_read, pins.crcs,
        "{name}: the images, each with its header's version written back to the format its round read"
    );
    assert_eq!(d.couplings, pins.couplings, "{name}: the image's couplings");
}

/// The derivations on one network (brief 067, brief 068), a test of their own: every rule run in
/// ADR-0165's order on the site's prior at the site's size, everything dumped before anything is
/// held, then the pinned tables.
fn site_derivation(site: &Site) {
    let name = format!("{} derivation", site.name);
    let d = derive_at(site.units, site.seed, &name);
    dump_derivation(&name, &d);
    eprintln!(
        "DUMP {name} verdict of this network on clause 0: {}; the prediction, none: {SEEDED_PREDICTED:?}",
        d.rules.hold()
    );
    derivation_held(&name, &site.derivation, &d);
}

/// The derivations on H-33's network of index `n` in `SEEDS` (brief 067).
fn seeded_derivation(n: usize) {
    site_derivation(&seeded_site(n));
}

// ---------------------------------------------------------------- the run (brief 067)

/// One arm on a network (brief 067; the network a `Site` since brief 068): the derivation by the
/// rules at the site's size, held to the site's pinned derivation, which is this arm's
/// calibration — on a network whose clause 0 does not hold there is no arm — then H-25's arm from
/// H-25's image of this network: 7 680 trials under the drawn delivery with no task critic and
/// H-20's flips, the drawn sources held to the critic's oracle's counts and the composer and the
/// network's oracle held to the record at every trial (`fed_run_at`, H-25's run with no shadow
/// beside it). Beside the run, at every trial's end, the critic's step is read (`Stepped`) from
/// the weights before and after the reward and the window's counts, and held to the engine's own
/// value. Everything is dumped, and the clauses and the readings computed, before anything is
/// held; then the pinned tables of the run, by block. At the end the executor is shut down and
/// every worker's report held to no entry dropped.
///
/// Since ADR-0174 the body is `arm_on`'s, which runs an arm on any network under any feedback:
/// this is `arm_on` on the site under the true reward, and reads what it read.
fn site_arm(site: &Site, arm: Reversal) {
    arm_on(Ground::Site(site), None, arm);
}

/// One arm of H-33 on the network of index `n` in `SEEDS` (brief 067).
fn seeded_arm(n: usize, arm: Reversal) {
    site_arm(&seeded_site(n), arm);
}

/// The rules on the instrument's own prior (brief 067, H-33's calibration): `derive` at seed 22
/// returns every constant the tree holds, each table it reads is the table an earlier round
/// pinned, and the image it writes is H-25's, by the CRC of every image on the way to it.
#[test]
#[ignore]
fn the_rules_return_the_tree_s_constants_on_seed_22_at_1024_units_exhaustive() {
    let name = "rules1024 seed 22";
    let d = derive(PRIOR_SEED, name);
    dump_derivation(name, &d);
    assert_eq!(
        d.rules, RULES_1024,
        "{name}: each rule returns its constant"
    );
    assert!(
        d.rules.hold(),
        "{name}: clause 0 holds on the instrument's prior"
    );
    assert_eq!(d.scanned.len(), 1, "{name}: the first rotation is balanced");
    assert_eq!(d.prior_sums, PRIOR_SUMS_1024, "{name}: the prior's sums");
    assert_eq!(
        d.calibrations.as_slice(),
        &CALIBRATION_1024[..1],
        "{name}: the calibration's block at the first gain, which passes"
    );
    assert_eq!(
        d.census.as_slice(),
        VOLLEY_TICKS_1024.as_slice(),
        "{name}: ADR-0072's census"
    );
    assert_eq!(d.synapses, SYNAPSES_1024, "{name}: ADR-0072's synapses");
    assert_eq!(
        d.cancelled.as_slice(),
        &CANCELLED_1024[..2],
        "{name}: ADR-0076's first two candidates, the second picked"
    );
    for (probe, &messages) in d.probes.iter().zip(&CANCELS) {
        let pinned = PROBED_CANCEL_1024
            .iter()
            .find(|&&(_, cancel, _)| cancel == Some(cancel_of(messages)))
            .map(|&(_, _, ticks)| ticks);
        assert_eq!(
            Some(probe.as_slice()),
            pinned,
            "{name}: ADR-0076's probe of {messages}"
        );
    }
    assert_eq!(d.probes.len(), 2, "{name}: two candidates tried");
    assert_eq!(
        d.lead_in.as_slice(),
        BACKGROUND_LEAD_IN_1024[SETTLED],
        "{name}: ADR-0077's lead-in"
    );
    assert_eq!(
        d.quiet,
        Some(QUIET_1024[SETTLED]),
        "{name}: ADR-0077's quiet run"
    );
    assert_eq!(
        d.frozen,
        Some(BACKGROUND_1024[SETTLED]),
        "{name}: ADR-0077's frozen block"
    );
    assert_eq!(
        d.counted.as_slice(),
        BACKGROUND_COUNTED_1024[SETTLED].as_slice(),
        "{name}: ADR-0077's counts"
    );
    assert_eq!(
        d.frozen_census.as_slice(),
        BACKGROUND_CENSUS_1024[SETTLED],
        "{name}: ADR-0077's census"
    );
    assert_eq!(
        d.target_lead_in.as_slice(),
        TARGET_LEAD_IN_1024.as_slice(),
        "{name}: ADR-0129's lead-in"
    );
    assert_eq!(
        d.crcs
            .map(|crcs| [crcs[1], crcs[2], crcs[3], crcs[4], crcs[5]]),
        Some([
            REVERSAL_IMAGE_CRC_1024,
            PUNISHED_IMAGE_CRC_1024,
            TARGET_IMAGE_CRC_1024,
            VALUED_IMAGE_CRC_1024,
            WINDOWED_IMAGE_CRC_1024
        ]),
        "{name}: H-17's image, H-20's, H-21's, H-22's and H-23's, the one H-25's arms decode"
    );
    assert_eq!(
        d.couplings,
        Some(IMAGE_COUPLINGS_1024),
        "{name}: the image's couplings"
    );
    let made = d.made.as_ref().expect("a configuration");
    assert_eq!(
        (
            made.derived,
            made.gain,
            made.sums,
            made.couplings,
            made.period,
            made.window,
            made.critic
        ),
        (
            DERIVED_1024,
            GAIN_1024,
            QUIET_1024[SETTLED].1,
            IMAGE_COUPLINGS_1024,
            TARGET_PERIOD_1024,
            WINDOW_TICKS_1024,
            VALUED_CRITIC
        ),
        "{name}: what a rewarded run takes from the network is what the tree holds"
    );
    assert_eq!(
        crc64(&made.windowed),
        WINDOWED_IMAGE_CRC_1024,
        "{name}: the image an arm would decode is H-25's"
    );
}

